SELECT (m->>'users_total')::bigint AS users_total,(m->>'users_active_30d')::bigint AS users_active_30d,(m->>'profiles_total')::bigint AS profiles_total,(m->>'users_studying')::bigint AS users_studying,(m->>'ranking_records')::bigint AS ranking_records,(m->>'contests_active')::bigint AS contests_active,(m->>'contests_total')::bigint AS contests_total,(m->>'study_users')::bigint AS study_users,(m->>'study_cycles')::bigint AS study_cycles,(m->>'study_sessions')::bigint AS study_sessions,(m->>'study_groups_active')::bigint AS study_groups_active,(m->>'study_group_members')::bigint AS study_group_members,(m->>'subscriptions_active')::bigint AS subscriptions_active,(m->>'app_errors_24h')::bigint AS app_errors_24h,m->>'pci_last_status' AS pci_last_status,m->>'pci_last_finished_at' AS pci_last_finished_at,(m->>'pci_last_items_upserted')::bigint AS pci_last_items_upserted FROM (SELECT zabbix_monitoring.dashboard_metrics() AS m) q;
